page_styles.fullscreen:
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #ffffff;
  touch-action: none;
  overscroll-behavior: none;
}
canvas {
  display: block;
  touch-action: none;
}

page_styles.preview:
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  overflow: hidden;
  background: #eff6ff;
  cursor: pointer;
}
canvas {
  display: block;
  cursor: auto;
}

page_styles.live:
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  overflow: hidden;
  background: #eff6ff;
}
canvas {
  display: block;
}
